import{_ as a,o as t,c as n,ag as o}from"./chunks/framework.CbQjVMS6.js";const p=JSON.parse('{"title":"When a growing company actually needs master data management","description":"","frontmatter":{},"headers":[],"relativePath":"insights/master-data-management.md","filePath":"insights/master-data-management.md","lastUpdated":1794023466000}'),r={name:"insights/master-data-management.md"};function i(s,e,d,l,h,m){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="when-a-growing-company-actually-needs-master-data-management" tabindex="-1">When a growing company actually needs master data management <a class="header-anchor" href="#when-a-growing-company-actually-needs-master-data-management" aria-label="Permalink to &quot;When a growing company actually needs master data management&quot;">​</a></h1><p><em>Published 6 November 2026 · 7 min read</em></p><p>Master data management (MDM) has a reputation problem. It is sold as an enterprise programme with a steering committee, a multi-year roadmap and a six-figure licence. For many growing companies that framing is absurd: they have a few thousand customers, a product catalogue and a finance system, not a global governance function.</p><p>But the underlying problem is real. Once several systems hold the same entities, someone has to decide which record is authoritative. This article describes the symptoms that justify MDM, the smallest useful implementation, and the order in which to fix things.</p><h2 id="what-counts-as-master-data" tabindex="-1">What counts as master data <a class="header-anchor" href="#what-counts-as-master-data" aria-label="Permalink to &quot;What counts as master data&quot;">​</a></h2><p>Master data is the small set of entities that many processes refer to:</p><ul><li><strong>Parties</strong> — customers, prospects, suppliers, partners</li><li><strong>Products</strong> — items, SKUs, product families, service offerings</li><li><strong>Organisations</strong> — legal entities, business units, sites</li><li><strong>Reference data</strong> — currencies, units, countries, industry codes, tax categories</li><li><strong>Materials and assets</strong> — in manufacturing and maintenance contexts</li></ul><p>Transactional data (orders, invoices, tickets) is not master data, although it references it. The distinction matters because master data changes slowly and is reused widely; that is exactly why inconsistency is expensive.</p><h2 id="symptoms-worth-acting-on" tabindex="-1">Symptoms worth acting on <a class="header-anchor" href="#symptoms-worth-acting-on" aria-label="Permalink to &quot;Symptoms worth acting on&quot;">​</a></h2><p>You do not need MDM because a vendor says so. You need it when one or more of these are true:</p><h3 id="_1-the-same-entity-has-different-identifiers-in-different-systems" tabindex="-1">1. The same entity has different identifiers in different systems <a class="header-anchor" href="#_1-the-same-entity-has-different-identifiers-in-different-systems" aria-label="Permalink to &quot;1. The same entity has different identifiers in different systems&quot;">​</a></h3><p>A customer exists as <code>CUST-1042</code> in the ERP, <code>acme.example</code> in the CRM and “ACME Pte Ltd” in finance. Reconciling them consumes analyst time every month, and the reconciliation is never quite complete.</p><h3 id="_2-reporting-disagrees-with-itself" tabindex="-1">2. Reporting disagrees with itself <a class="header-anchor" href="#_2-reporting-disagrees-with-itself" aria-label="Permalink to &quot;2. Reporting disagrees with itself&quot;">​</a></h3><p>Two dashboards show different revenue or supplier counts. The meeting is spent arguing about definitions instead of decisions. Each system is internally consistent; the organisation is not.</p><h3 id="_3-onboarding-a-system-requires-a-manual-data-project" tabindex="-1">3. Onboarding a system requires a manual data project <a class="header-anchor" href="#_3-onboarding-a-system-requires-a-manual-data-project" aria-label="Permalink to &quot;3. Onboarding a system requires a manual data project&quot;">​</a></h3><p>Every new tool needs a spreadsheet of customers, products and codes, cleaned by hand. The integration is done once and then drifts immediately.</p><h3 id="_4-approval-and-ownership-are-unclear" tabindex="-1">4. Approval and ownership are unclear <a class="header-anchor" href="#_4-approval-and-ownership-are-unclear" aria-label="Permalink to &quot;4. Approval and ownership are unclear&quot;">​</a></h3><p>Anyone can edit a customer record. No one can say who approved a change, why a supplier was blocked, or when a product code was introduced. Audits become archaeology.</p><h3 id="_5-ai-or-automation-projects-stall-on-data-quality" tabindex="-1">5. AI or automation projects stall on data quality <a class="header-anchor" href="#_5-ai-or-automation-projects-stall-on-data-quality" aria-label="Permalink to &quot;5. AI or automation projects stall on data quality&quot;">​</a></h3><p>An assistant cannot answer “how many active suppliers do we have in Vietnam” if the answer depends on which system you ask. AI amplifies data quality; it does not fix it.</p><p>If none of these apply, you probably do not need MDM yet. A shared spreadsheet with an owner may be enough. The cost of governance is real, and premature MDM becomes another silo.</p><h2 id="the-smallest-useful-mdm" tabindex="-1">The smallest useful MDM <a class="header-anchor" href="#the-smallest-useful-mdm" aria-label="Permalink to &quot;The smallest useful MDM&quot;">​</a></h2><p>A minimum viable MDM has five components:</p><ol><li><strong>A model.</strong> Define each entity, its fields, types, required constraints and relationships. Treat the model as versioned code, not a diagram in a slide deck.</li><li><strong>A golden record.</strong> For each entity, define which source wins for which field, or require a steward to make the choice. Store the result with its provenance.</li><li><strong>A workflow.</strong> Changes to master data go through review and approval. The workflow should be configurable but not infinitely so.</li><li><strong>An access model.</strong> Roles, permissions and menus determine who can propose, approve and publish changes.</li><li><strong>An API.</strong> Downstream systems read the golden record through a documented interface. Without an API, the MDM becomes a read-only report.</li></ol><p>Everything else (data quality dashboards, matching algorithms, hierarchy management) can be added later. Starting with these five keeps the first release small enough to finish.</p><h2 id="build-the-model-before-the-cleanup" tabindex="-1">Build the model before the cleanup <a class="header-anchor" href="#build-the-model-before-the-cleanup" aria-label="Permalink to &quot;Build the model before the cleanup&quot;">​</a></h2><p>Teams often begin with a data cleanup project: deduplicate customers, normalise supplier names, fix product codes. The cleanup produces a one-time improvement that decays as soon as new records arrive.</p><p>A better order is:</p><ol><li><strong>Model first.</strong> Agree on fields, identifiers and relationships.</li><li><strong>Then govern.</strong> Assign owners and approval rules for each domain.</li><li><strong>Then migrate.</strong> Load and reconcile existing records against the model.</li><li><strong>Then integrate.</strong> Connect downstream systems to the API.</li><li><strong>Then measure.</strong> Track duplicates, missing fields, approval latency and adoption.</li></ol><p>The model is the contract. Without it, cleanup has no definition of “clean”.</p><h2 id="build-versus-buy" tabindex="-1">Build versus buy <a class="header-anchor" href="#build-versus-buy" aria-label="Permalink to &quot;Build versus buy&quot;">​</a></h2><p>Commercial MDM suites are mature and expensive. They make sense for large organisations with complex hierarchies, multi-domain governance and dedicated data teams. They are usually a poor fit for a growing company that needs a clear model, an approval workflow and an API.</p><p>Open-source options change the calculus. A self-hosted platform such as <a href="https://pieteams.github.io/piemdm/" target="_blank" rel="noreferrer">PieMDM</a> provides modelling, dictionaries, entity management, approval flows, permissions and an OpenAPI surface without licence fees. The trade-off shifts from licence cost to implementation effort: you still need to define the model and convince people to follow the workflow.</p><p>The honest comparison is total cost of ownership:</p><table tabindex="0"><thead><tr><th>Factor</th><th>Commercial suite</th><th>Self-hosted open source</th></tr></thead><tbody><tr><td>Licence</td><td>Recurring, often per user</td><td>None (MIT)</td></tr><tr><td>Implementation</td><td>Vendor or partner led</td><td>Internal or integrator led</td></tr><tr><td>Customisation</td><td>Configuration plus vendor roadmap</td><td>Direct code changes</td></tr><tr><td>Upgrade path</td><td>Vendor managed</td><td>Your responsibility</td></tr><tr><td>Lock-in</td><td>Moderate to high</td><td>Low: data and schema are yours</td></tr></tbody></table><p>For a company with competent IT and a bounded domain, self-hosting is often the better trade. For a multinational with regulatory complexity, a vendor may still be right.</p><h2 id="common-failure-modes" tabindex="-1">Common failure modes <a class="header-anchor" href="#common-failure-modes" aria-label="Permalink to &quot;Common failure modes&quot;">​</a></h2><ul><li><strong>Boiling the ocean.</strong> Trying to govern every domain at once. Start with one entity that causes visible pain.</li><li><strong>Governance without tooling.</strong> A policy document that no system enforces.</li><li><strong>Tooling without governance.</strong> A platform nobody is accountable for maintaining.</li><li><strong>Perfect matching.</strong> Spending months on fuzzy matching before publishing a single golden record.</li><li><strong>Ignoring the API.</strong> If downstream systems cannot consume the data, the MDM is a reporting tool.</li></ul><h2 id="a-pragmatic-starting-point" tabindex="-1">A pragmatic starting point <a class="header-anchor" href="#a-pragmatic-starting-point" aria-label="Permalink to &quot;A pragmatic starting point&quot;">​</a></h2><p>Pick one domain — usually customers or suppliers. Define twenty fields, not two hundred. Assign one steward. Configure one approval flow. Publish one API endpoint. Measure duplicate rate and time-to-approve for a quarter. If the process holds, expand the model. If it does not, fix the process before adding domains.</p><p>MDM is not a product you install; it is an agreement about which data is authoritative and who may change it. Software makes the agreement enforceable. It cannot make it for you.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://pieteams.github.io/piemdm/getting-started/what-is-piemdm" target="_blank" rel="noreferrer">What is PieMDM</a> — architecture and technology choices</li><li><a href="https://pieteams.github.io/piemdm/getting-started/master-data-system" target="_blank" rel="noreferrer">Master data systems</a> — the landscape of MDM platforms</li><li><a href="https://pieteams.github.io/piemdm/guide/approval-flow" target="_blank" rel="noreferrer">PieMDM approval flows</a> — how governed changes work</li></ul>',43)])])}const u=a(r,[["render",i]]);export{p as __pageData,u as default};
